const key = String($env.TOPIS_API_KEY ?? '').trim();

return [{
  json: {
    centerX: 205217,
    centerY: 444228,
    radiusM: 1500,
    regionPrefixes: ['121', '122', '123'],
    pageSize: key === 'sample' ? 5 : 1000,
    hasKey: key.length > 0,
    ok: false,
    reason: key.length > 0 ? null : 'NO_KEY',
    candidateCount: 0,
    inRadiusCount: 0,
    upserted: 0,
    softDeleted: 0,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ok: false,
    reason: context.reason || 'UNKNOWN',
    candidateCount: Number(context.candidateCount || 0),
    inRadiusCount: Number(context.inRadiusCount || 0),
    upserted: Number(context.upserted || 0),
    softDeleted: Number(context.softDeleted || 0),
  },
}];

const settings = $('설정').first().json;
const response = $input.first().json;
const status = Number(response.statusCode);
const body = typeof response.body === 'string' ? response.body : '';

function tagValue(xml, tagName) {
  const match = xml.match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
  return match ? match[1].replace(/^\s*<!\[CDATA\[/, String()).replace(/\]\]>/, String()).trim() : null;
}

function reasonFor(stage, httpStatus, code) {
  if (httpStatus !== 200) return `${stage}_${Number.isInteger(httpStatus) ? `HTTP_${httpStatus}` : 'HTTP_ERROR'}`;
  const safeCode = code && /^[A-Z0-9_-]{1,50}$/.test(code) ? code : code ? 'RESULT_CODE_INVALID' : 'RESULT_CODE_MISSING';
  return `${stage}_${safeCode}`;
}

const code = tagValue(body, 'CODE');
if (status !== 200 || code !== 'INFO-000') {
  return [{ json: { ...settings, ok: false, reason: reasonFor('ROAD_DIV', status, code) } }];
}

const roadDivs = [...body.matchAll(/<row(?:\s[^>]*)?>([\s\S]*?)<\/row>/gi)]
  .map((match) => tagValue(match[1], 'road_div_cd'))
  .filter((value) => value && /^[A-Za-z0-9_-]{1,20}$/.test(value));
const uniqueRoadDivs = [...new Set(roadDivs)];

return [{
  json: {
    ...settings,
    ok: uniqueRoadDivs.length > 0,
    reason: uniqueRoadDivs.length > 0 ? null : 'ROAD_DIV_INVALID_DATA',
    roadDivs: uniqueRoadDivs,
  },
}];

const context = $input.first().json;

return context.roadDivs.map((roadDivCd) => ({
  json: { roadDivCd, start: 1, end: context.pageSize },
}));

const settings = $('설정').first().json;
const axes = [];
const extraRequests = [];
let failureReason = null;

function tagValue(xml, tagName) {
  const match = xml.match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
  return match ? match[1].replace(/^\s*<!\[CDATA\[/, String()).replace(/\]\]>/, String()).trim() : null;
}

function responseReason(stage, status, code) {
  if (status !== 200) return `${stage}_${Number.isInteger(status) ? `HTTP_${status}` : 'HTTP_ERROR'}`;
  const safeCode = code && /^[A-Z0-9_-]{1,50}$/.test(code) ? code : code ? 'RESULT_CODE_INVALID' : 'RESULT_CODE_MISSING';
  return `${stage}_${safeCode}`;
}

for (const item of $input.all()) {
  const response = item.json;
  const status = Number(response.statusCode);
  const body = typeof response.body === 'string' ? response.body : '';
  const code = tagValue(body, 'CODE');
  if (status !== 200 || code !== 'INFO-000') {
    failureReason ||= responseReason('ROAD_INFO', status, code);
    continue;
  }

  const totalText = tagValue(body, 'list_total_count');
  const total = totalText && /^\d+$/.test(totalText) ? Number(totalText) : null;
  if (!Number.isSafeInteger(total) || total < 0) {
    failureReason ||= 'ROAD_INFO_INVALID_DATA';
    continue;
  }

  for (const match of body.matchAll(/<row(?:\s[^>]*)?>([\s\S]*?)<\/row>/gi)) {
    const axisCd = tagValue(match[1], 'axis_cd');
    if (axisCd && /^[A-Za-z0-9_-]{1,20}$/.test(axisCd)) axes.push(axisCd);
  }

  for (let start = settings.pageSize + 1; start <= total; start += settings.pageSize) {
    extraRequests.push({
      roadDivCd: String(response.roadDivCd),
      start,
      end: Math.min(start + settings.pageSize - 1, total),
    });
  }
}

return [{
  json: {
    ...settings,
    ok: failureReason === null,
    reason: failureReason,
    axes: [...new Set(axes)],
    extraRequests,
    hasExtra: extraRequests.length > 0,
  },
}];

