const context = $input.first().json;
const byLinkId = new Map();

for (const link of context.links) {
  const current = byLinkId.get(link.linkId);
  if (!current || (!current.axisDir && link.axisDir)) byLinkId.set(link.linkId, link);
}

const candidates = [...byLinkId.values()]
  .filter((link) => context.regionPrefixes.includes(link.linkId.slice(0, 3)))
  .sort((left, right) => left.linkId.localeCompare(right.linkId));

return [{
  json: {
    ...context,
    links: undefined,
    extraRequests: undefined,
    candidates,
    candidateCount: candidates.length,
    hasCandidates: candidates.length > 0,
  },
}];

const context = $input.first().json;

return context.candidates.map((link) => ({
  json: {
    linkId: link.linkId,
    axisDir: link.axisDir,
    end: context.pageSize,
  },
}));

const context = $('링크 접두사 사전 필터').first().json;
const inRadiusLinks = [];
let failureReason = null;

function tagValue(xml, tagName) {
  const match = xml.match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
  return match ? match[1].replace(/^\s*<!\[CDATA\[/, String()).replace(/\]\]>/, String()).trim() : null;
}

function responseReason(status, code) {
  if (status !== 200) return `LINK_VERTEX_${Number.isInteger(status) ? `HTTP_${status}` : 'HTTP_ERROR'}`;
  const safeCode = code && /^[A-Z0-9_-]{1,50}$/.test(code) ? code : code ? 'RESULT_CODE_INVALID' : 'RESULT_CODE_MISSING';
  return `LINK_VERTEX_${safeCode}`;
}

for (const item of $input.all()) {
  const response = item.json;
  const status = Number(response.statusCode);
  const body = typeof response.body === 'string' ? response.body : '';
  const code = tagValue(body, 'CODE');
  if (status !== 200 || code !== 'INFO-000') {
    failureReason ||= responseReason(status, code);
    continue;
  }

  const distances = [];
  for (const match of body.matchAll(/<row(?:\s[^>]*)?>([\s\S]*?)<\/row>/gi)) {
    const x = Number(tagValue(match[1], 'GRS80TM_X'));
    const y = Number(tagValue(match[1], 'GRS80TM_Y'));
    if (Number.isFinite(x) && Number.isFinite(y)) {
      distances.push(Math.hypot(x - context.centerX, y - context.centerY));
    }
  }

  if (distances.length === 0) {
    failureReason ||= 'LINK_VERTEX_INVALID_DATA';
    continue;
  }

  const centerDistM = Math.round(Math.min(...distances));
  if (centerDistM <= context.radiusM) {
    inRadiusLinks.push({
      linkId: String(response.linkId),
      axisDir: response.axisDir || null,
      centerDistM,
    });
  }
}

return [{
  json: {
    ...context,
    ok: failureReason === null,
    reason: failureReason,
    inRadiusLinks,
    inRadiusCount: inRadiusLinks.length,
    hasInRadiusLinks: inRadiusLinks.length > 0,
  },
}];

const context = $('링크 정점 판정').first().json;
const links = [];
let failureReason = null;

function tagValue(xml, tagName) {
  const match = xml.match(new RegExp(`<${tagName}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tagName}>`, 'i'));
  return match ? match[1].replace(/^\s*<!\[CDATA\[/, String()).replace(/\]\]>/, String()).trim() : null;
}

function decodeXml(value) {
  return value
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, String.fromCharCode(34))
    .replace(/&apos;/g, String.fromCharCode(39))
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)))
    .replace(/&amp;/g, '&');
}

function responseReason(status, code) {
  if (status !== 200) return `LINK_INFO_${Number.isInteger(status) ? `HTTP_${status}` : 'HTTP_ERROR'}`;
  const safeCode = code && /^[A-Z0-9_-]{1,50}$/.test(code) ? code : code ? 'RESULT_CODE_INVALID' : 'RESULT_CODE_MISSING';
  return `LINK_INFO_${safeCode}`;
}

for (const item of $input.all()) {
  const response = item.json;
  const status = Number(response.statusCode);
  const body = typeof response.body === 'string' ? response.body : '';
  const code = tagValue(body, 'CODE');
  if (status !== 200 || code !== 'INFO-000') {
    failureReason ||= responseReason(status, code);
    continue;
  }

  const rowMatch = body.match(/<row(?:\s[^>]*)?>([\s\S]*?)<\/row>/i);
  const roadName = rowMatch ? tagValue(rowMatch[1], 'ROAD_NAME') : null;
  const stNodeName = rowMatch ? tagValue(rowMatch[1], 'ST_NODE_NM') : null;
  const edNodeName = rowMatch ? tagValue(rowMatch[1], 'ED_NODE_NM') : null;
  const distanceText = rowMatch ? tagValue(rowMatch[1], 'MAP_DIST') : null;
  const distance = Number(distanceText);

  if (roadName === null || stNodeName === null || edNodeName === null || !Number.isFinite(distance) || distance < 0) {
    failureReason ||= 'LINK_INFO_INVALID_DATA';
    continue;
  }

  links.push({
    linkId: String(response.linkId),
    roadName: decodeXml(roadName),
    stNodeName: decodeXml(stNodeName),
    edNodeName: decodeXml(edNodeName),
    axisDir: response.axisDir || null,
    distanceM: Math.round(distance),
    centerDistM: Number(response.centerDistM),
  });
}

return [{
  json: {
    ...context,
    ok: failureReason === null && links.length === context.inRadiusCount,
    reason: failureReason || (links.length === context.inRadiusCount ? null : 'LINK_INFO_INVALID_DATA'),
    links,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ...context,
    ok: true,
    reason: null,
    inRadiusLinks: [],
    inRadiusCount: 0,
    links: [],
  },
}];

const context = $input.first().json;
const replacements = [];
let query;

if (context.links.length === 0) {
  query = 'SELECT $1 AS UPSERTED';
  replacements.push(0);
} else {
  let parameter = 1;
  const valueGroups = context.links.map((link) => {
    const placeholders = [];
    for (const value of [link.linkId, link.roadName, link.stNodeName, link.edNodeName, link.axisDir, link.distanceM, link.centerDistM]) {
      placeholders.push(`$${parameter}`);
      replacements.push(value);
      parameter += 1;
    }
    return `('TOPIS', 'DAECHI', ${placeholders[0]}, NULL, ${placeholders[1]}, ${placeholders[2]}, ${placeholders[3]}, ${placeholders[4]}, ${placeholders[5]}, ${placeholders[6]}, NOW(), 'SYSTEM', NOW(), 'SYSTEM', 0)`;
  });

  query = `INSERT INTO TRAFFIC_LINK (SOURCE, AREA_CODE, LINK_ID, ROUTE_ID, ROAD_NAME, ST_NODE_NAME, ED_NODE_NAME, AXIS_DIR, DISTANCE_M, CENTER_DIST_M, CREATE_DT, CREATE_USER, UPDATE_DT, UPDATE_USER, DELETE_YN)\nVALUES ${valueGroups.join(',\n')}\nON DUPLICATE KEY UPDATE AREA_CODE = VALUES(AREA_CODE), ROUTE_ID = VALUES(ROUTE_ID), ROAD_NAME = VALUES(ROAD_NAME), ST_NODE_NAME = VALUES(ST_NODE_NAME), ED_NODE_NAME = VALUES(ED_NODE_NAME), AXIS_DIR = VALUES(AXIS_DIR), DISTANCE_M = VALUES(DISTANCE_M), CENTER_DIST_M = VALUES(CENTER_DIST_M), UPDATE_DT = NOW(), UPDATE_USER = 'SYSTEM', DELETE_YN = 0`;
}

return [{ json: { ...context, query, replacements } }];

const context = $('정상 링크 적재 준비').first().json;
const failed = $input.all().some((item) => item.json.error != null);

return [{
  json: {
    ...context,
    ok: !failed,
    reason: failed ? 'DB_UPSERT_FAILED' : null,
    upserted: failed ? 0 : context.links.length,
  },
}];

const context = $input.first().json;
const replacements = [1];
let parameter = 2;
let query = "SELECT COUNT(*) AS STALE_COUNT\nFROM TRAFFIC_LINK\nWHERE SOURCE = 'TOPIS' AND DELETE_YN = 0 AND $1 = 1";

if (context.links.length > 0) {
  // n8n MySQL 노드는 숫자처럼 보이는 값을 숫자로 바꾼다. 링크 ID를 문자열로 비교하도록 JSON 문자열 하나로 넘긴다.
  // JSON 경로는 큰따옴표로 쓴다. 쿼리 식을 펼칠 때 String.replace가 작은따옴표 앞의 $를 특수 패턴으로 읽는다.
  replacements.push(JSON.stringify(context.links.map((link) => String(link.linkId))));
  query += `\n  AND LINK_ID NOT IN (SELECT j.LINK_ID FROM JSON_TABLE($${parameter}, "$[*]" COLUMNS (LINK_ID VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH "$")) j)`;
}

return [{ json: { ...context, query, replacements } }];

const context = $('삭제 대상 조회 준비').first().json;
const rows = $input.all().map((item) => item.json);
const failed = rows.some((row) => row.error != null);
const countRow = rows.find((row) => row.STALE_COUNT != null);
const staleCount = countRow ? Number(countRow.STALE_COUNT) : null;
const validCount = Number.isSafeInteger(staleCount) && staleCount >= 0;

return [{
  json: {
    ...context,
    ok: !failed && validCount,
    reason: failed ? 'DB_STALE_COUNT_FAILED' : validCount ? null : 'DB_STALE_COUNT_INVALID',
    staleCount: validCount ? staleCount : 0,
  },
}];

const context = $input.first().json;
const replacements = [1];
let parameter = 2;
let query = "UPDATE TRAFFIC_LINK\nSET DELETE_YN = 1, UPDATE_DT = NOW(), UPDATE_USER = 'SYSTEM'\nWHERE SOURCE = 'TOPIS' AND DELETE_YN = 0 AND $1 = 1";

if (context.links.length > 0) {
  // n8n MySQL 노드는 숫자처럼 보이는 값을 숫자로 바꾼다. 링크 ID를 문자열로 비교하도록 JSON 문자열 하나로 넘긴다.
  // JSON 경로는 큰따옴표로 쓴다. 쿼리 식을 펼칠 때 String.replace가 작은따옴표 앞의 $를 특수 패턴으로 읽는다.
  replacements.push(JSON.stringify(context.links.map((link) => String(link.linkId))));
  query += `\n  AND LINK_ID NOT IN (SELECT j.LINK_ID FROM JSON_TABLE($${parameter}, "$[*]" COLUMNS (LINK_ID VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci PATH "$")) j)`;
}

return [{ json: { ...context, query, replacements } }];

const context = $('빠진 링크 삭제 표시 준비').first().json;
const failed = $input.all().some((item) => item.json.error != null);

return [{
  json: {
    ...context,
    ok: !failed,
    reason: failed ? 'DB_SOFT_DELETE_FAILED' : null,
    softDeleted: failed ? 0 : context.staleCount,
  },
}];

const context = $input.first().json;

return [{
  json: {
    ok: true,
    reason: null,
    candidateCount: context.candidateCount,
    inRadiusCount: context.inRadiusCount,
    upserted: context.upserted,
    softDeleted: context.softDeleted,
  },
}];
